pub fn find(name: &str) -> Option<&'static LanguagePackageRef> {
    LANGUAGES.iter().find(|entry| {
        entry.id.eq_ignore_ascii_case(name)
            || entry
                .aliases
                .iter()
                .any(|alias| alias.eq_ignore_ascii_case(name))
    })
}
